// and its two entries should lay out side by side (row), not stack in a column.
await page.goto('/login');
const bar = page.getByRole('navigation').first();
await expect(bar).toBeVisible();
await expect(bar).toHaveCSS('flex-direction', 'row');
await expect(bar.getByRole('link')).toHaveCount(2);
